private fun loadJson(url: String): Promise<String> {
    return Promise { resolve, _ ->
        XMLHttpRequest().apply {
            open("GET", url)
            responseType = XMLHttpRequestResponseType.JSON
            onerror = { println("Failed to get Json") }
            onload = {
                resolve(JSON.stringify(response))
            }
            send()
        }
    }
}


fun createDB() {
    config(LocalForageConfig("starfield-eye"))
}

fun persistMemory() {
    LocalForage.setItem("memory", jsonMapper.encodeToString(inMemoryStorage))
}

fun persistPictures() {
    LocalForage.setItem("pictures", jsonMapper.encodeToString(pictureStorage))
}

fun loadMemory(): Promise<*> {
    return LocalForage.getItem("memory").then { persisted ->
        if (persisted != null && persisted != undefined) {
            try {
                inMemoryStorage = jsonMapper.decodeFromString(persisted as String)
            } catch (e: Exception) {
                println("Failed to parse memory. Try deleting user data and rebuilding it.")
            }
        }
    }
}

fun loadPictures(status: HTMLElement): Promise<*> {
    return LocalForage.getItem("pictures").then { persisted ->
        if (persisted != null && persisted != undefined) {
            decodePictures(persisted as String, status)
        }
    }
}

fun exportPlayerInfo() = exportData(jsonMapper.encodeToString(inMemoryStorage), "StarfieldEye.json")

fun exportPictures() = exportData(jsonMapper.encodeToString(pictureStorage), "StarfieldPictures.json")

private fun exportData(data: String, fileName: String) {
    val download = document.createElement("a") as HTMLElement
    download.setAttribute("href", "data:text/plain;charset=utf-8,$data")
    download.setAttribute("download", fileName)
    document.body?.append(download)
    download.click()
    document.body?.removeChild(download)
}

fun importPlayerInfo(status: HTMLElement) {
    importData { data ->
        try {
            decodeInMemoryStorage(data, status)
            println("Imported ${inMemoryStorage.planetUserInfo.size} user info pieces")
            persistMemory()
            status.innerText = "Player Info Imported. Check console for additional logs"
        } catch (e: Exception) {
            println("Import failed")
            status.innerText = "Import failed"
        }
    }
}

fun importPictures(status: HTMLElement) {
    importData { data ->
        try {
            decodePictures(data, status)
            println("Imported ${pictureStorage.keys.size} pictures")
            persistPictures()
            status.innerText = "Pictures Imported"
        } catch (e: Exception) {
            println("Import failed")
            status.innerText = "Import failed"
        }
    }
}

private fun importData(then: (String) -> Unit) {
    val fileInput = document.createElement("input") as HTMLInputElement
    fileInput.apply {
        type = "file"
        accept = "*.json"
        addEventListener("change", { e: Event ->
            if (files != null) {
                val file = files!![0]!!
                val reader = FileReader()
                reader.onloadend = {
                    then(reader.result as String)
                }
                reader.readAsText(file)
            }
        })
        dispatchEvent(MouseEvent("click"))
    }
}

fun deleteUserData() {
    if (window.confirm("Are you sure you want to delete data? Make sure you've exported a backup first!")) {
        inMemoryStorage = InMemoryStorage()
        pictureStorage = mutableMapOf()
        persistMemory()
    }
}

fun savePicture(key: String, data: String) {
    pictureStorage[key] = data
    persistPictures()
}

fun deletePicture(key: String) {
    pictureStorage.remove(key)
    persistPictures()
}

fun loadSampleData(status: HTMLElement) {
    try {
        status.innerText = "Loading Player Info"
        loadJson("sample/StarfieldEye.json").then { playerJson ->
            loadJson("sample/StarfieldPictures.json").then { pictureJson ->
                try {
                    var success = decodeInMemoryStorage(playerJson, status)
                    if(success) status.innerText = "Loading Pictures"
                    success = success && decodePictures(pictureJson, status)
                    println("Imported ${pictureStorage.keys.size} pictures")
                    persistMemory()
                    persistPictures()
                    if (success) {
                        status.innerText = "Loaded sample data!"
                    }
                } catch (e: Throwable) {
                    status.innerText = "Loading sample data failed"
                }
            }
        }
    } catch (e: Exception) {
        status.innerText = "Loading sample data failed"
    }
}

private fun decodeInMemoryStorage(json: String, status: HTMLElement): Boolean {
    return try {
        jsonMapper.decodeFromString<InMemoryStorage>(json).also { inMemoryStorage = it }
        true
    } catch (e: Exception) {
        status.innerText = "Decoding Data Failed. Running migration"
        val migrated = migrateInMemoryStorage(json)
        if (!migrated) {
            val message = "Failed to migrate data! Consider saving json from the console. Then delete user data and rebuild it."
            status.innerText = message
            println(message)
        }
        migrated
    }
}

private fun decodePictures(json: String, status: HTMLElement): Boolean {
    return try {
        jsonMapper.decodeFromString<Map<String, String>>(json)
            .also { pictureStorage = it.toMutableMap() }
        if (isLegacyPictureStorage()) {
            val migrated = migratePictures(pictureStorage)
            if (!migrated) status.innerText = "Failed to migrate pictures! Consider saving json from the console. Then delete user data and rebuild it."
            migrated
        } else true
    } catch (e: Exception) {
        status.innerText = "Failed to parse pictures. Try deleting user data and rebuilding it."
        println("Failed to parse pictures. Try deleting user data and rebuilding it.")
        false
    }
}

fun ResearchProject.getProjectState(): ProjectState {
    val current = (inMemoryStorage.research[name] ?: 0)
    return when {
        current >= rank -> ProjectState.COMPLETED
        current < rank - 1 -> ProjectState.BLOCKED
        perks.entries.any { (reqPerk, reqLevel) -> (inMemoryStorage.perks[reqPerk] ?: 0) < reqLevel } -> ProjectState.BLOCKED

        else -> ProjectState.NONE
    }
}

fun ResearchProject.updateState(newState: ProjectState) {
    if (newState == ProjectState.COMPLETED) {
        inMemoryStorage.research[name] = rank
        //TODO Update other things
    } else if (newState == ProjectState.NONE) {
        inMemoryStorage.research[name] = rank - 1
        //TODO Update other things
    }
    persistMemory()
}
